"""Offline HTML/SVG report. No CDN, third-party assets or telemetry."""
import html,json
from pathlib import Path

def generate(directory,summary,metadata,requests,correctness):
    payload=json.dumps({'summary':summary,'metadata':metadata,'requests':requests,'correctness':correctness},ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>MLAI Evaluation</title><style>
body{font:15px system-ui,sans-serif;margin:0;background:#f5f6f8;color:#17202a}header,main{max-width:1200px;margin:auto;padding:28px}header{border-bottom:1px solid #ccd2db}h1{font-size:28px;margin:0 0 10px}h2{font-size:21px;margin:32px 0 14px}h3{font-size:16px}.muted{color:#596575}.cards{display:flex;gap:16px;flex-wrap:wrap}.card{padding:16px 22px;background:white;border:1px solid #d6dce4}.big{font-size:24px}table{border-collapse:collapse;background:white;width:100%;font-size:13px}td,th{text-align:left;border-bottom:1px solid #d6dce4;padding:9px;vertical-align:top}th{background:#e9edf2}.scroll{overflow:auto}svg{background:white;max-width:100%}.failed{color:#a02929}.passed{color:#1a6655}.skipped{color:#80621e}select,input{padding:8px;margin:0 12px 10px 0;border:1px solid #aab4c2}details{padding:10px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere}section{margin-bottom:26px}.note{border-left:3px solid #356c99;padding:10px 16px;background:#edf3f8}
</style><header><h1>MLAI · Evaluation & Benchmark</h1><div id="meta"></div></header><main>
<section><h2>Overview</h2><div id="overview" class="cards"></div><p class="note">API acknowledgment and automatic policy outcome are measured separately. Waiting for a manager, HR, employee correction, or handover is an automatic workflow stop, not final human resolution. Empty metrics display N/A.</p></section>
<section><h2>Performance</h2><div id="performance"></div><h3>API acknowledgment latency versus concurrency</h3><div id="latency"></div><h3>Throughput and batch completion</h3><div id="batches"></div></section>
<section><h2>Concurrency timeline</h2><select id="scenario"></select><input id="filter" placeholder="Request/case ID"><div id="timeline"></div><p class="muted">Axis: milliseconds from coordinated batch start. Queue timestamps use server wall clock. Missing internal rule spans are omitted; rule duration is available per request when exposed. Job service time includes VLM wrapper and persistence. READY inference is setup and excluded.</p></section>
<section><h2>VLM quality</h2><div id="vlm"></div></section>
<section><h2>LLM and default language behavior</h2><div id="llm"></div></section>
<section><h2>Rule engine & escalation</h2><div id="policy"></div><div id="escalation"></div></section>
<section><h2>Reliability</h2><div id="reliability"></div></section><section><h2>Security & privacy</h2><div id="security"></div></section>
<section><h2>Failure and skipped cases</h2><div id="failures"></div></section><section><h2>Before / after comparison</h2><p>Comparison is generated separately with the compare command. Two matching real run artifacts are required; no optimization improvement is inferred from this single run.</p></section>
<details><summary>Configuration and provenance</summary><pre id="provenance"></pre></details>
</main><script type="application/json" id="data">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),S=D.summary;
const esc=v=>String(v??'N/A').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const num=v=>v==null?'N/A':typeof v==='number'?v.toFixed(3):esc(v);
function table(columns,rows){return '<div class="scroll"><table><thead><tr>'+columns.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function section(id,v){const el=document.getElementById(id);if(v==null){el.textContent='N/A — not measured';return}el.innerHTML=table(['Metric','Measured value'],Object.entries(v).filter(([k])=>!['confusion_matrix','per_class'].includes(k)).map(([k,v])=>[k,v==null?'N/A':typeof v==='object'?JSON.stringify(v):v]));if(v.confusion_matrix){const labels=Object.keys(v.confusion_matrix);el.innerHTML+='<h3>Confusion matrix · rows expected, columns observed</h3>'+table(['Expected / observed',...labels],labels.map(l=>[l,...labels.map(a=>v.confusion_matrix[l][a])]));}}
document.getElementById('meta').textContent=D.metadata.run_id+' · '+D.metadata.timestamp+' · '+D.metadata.timing_kind;
document.getElementById('overview').innerHTML=Object.entries({...S.tests,requests:D.requests.length,unfinished:S.load_summary?.unfinished??null,automatic_outcome_rate:S.load_summary?.automatic_outcome_rate??null,duration_seconds:D.metadata.duration_seconds}).map(([k,v])=>'<div class="card"><div class="big">'+num(v)+'</div>'+esc(k)+'</div>').join('');
document.getElementById('performance').innerHTML=table(['Scenario','N concurrent','Category','Arrival','Inference','Samples','p50 ms','p95 ms','p99 ms','Mean ms','Errors','Unfinished'],(S.performance||[]).map(r=>[r.scenario,r.concurrency,r.category,r.arrival,r.mode,r.n,num(r.ack.p50_ms),num(r.ack.p95_ms),num(r.ack.p99_ms),num(r.ack.mean_ms),num(r.error_rate),r.unfinished]));
document.getElementById('batches').innerHTML=table(['Batch','Makespan s','Automatic outcomes/s','Business-final count','Unfinished','DB lock mean ms','DB tx mean ms'],(S.batches||[]).map(r=>[r.batch_id,num(r.makespan_seconds),num(r.outcomes_per_second),r.business_final_count,r.unfinished,num(r.sqlite_lock_wait.mean_ms),num(r.sqlite_transaction.mean_ms)]));
let perf=S.performance||[];let maxY=Math.max(1,...perf.map(r=>r.ack.p99_ms||0));let chart='<svg width="900" height="300" viewBox="0 0 900 300" role="img" aria-label="API acknowledgment latency in milliseconds versus concurrency"><path d="M70 20V245H870" stroke="#8896a6" fill="none"/><text x="400" y="286">Concurrent employees</text><text x="8" y="18">Latency (ms)</text>';
for(let tick=0;tick<5;tick++){let y=245-tick*52;chart+='<text x="12" y="'+y+'">'+(maxY*tick/4).toFixed(1)+'</text>'}
for(const [idx,p] of [.5,.95,.99].entries()){const color=['#356c99','#1a6655','#80621e'][idx];for(const r of perf){const y=245-(r.ack['p'+Math.round(p*100)+'_ms']||0)/maxY*208,x=70+r.concurrency/30*760;chart+='<circle cx="'+x+'" cy="'+y+'" r="4" fill="'+color+'"><title>'+esc(r.scenario+' '+r.category+' n='+r.concurrency+' p'+Math.round(p*100))+'</title></circle>'}chart+='<text x="'+(250+idx*150)+'" y="20" fill="'+color+'">p'+Math.round(p*100)+'</text>'}chart+='</svg><p class="muted">Source: this run; request latency quantiles. Hover points for scenario/category. Small samples produce unstable tail estimates.</p>';document.getElementById('latency').innerHTML=perf.length?chart:'N/A';
const selector=document.getElementById('scenario');selector.innerHTML='<option value="">All batches</option>'+[...new Set(D.requests.map(r=>r.batch_id))].map(s=>'<option>'+esc(s)+'</option>').join('');
function timeline(){const rr=D.requests.filter(r=>(!selector.value||r.batch_id===selector.value)&&(!document.getElementById('filter').value||String(r.case_id+' '+r.request_id).includes(document.getElementById('filter').value))).slice(0,80),max=Math.max(1,...rr.map(r=>r.final_offset_ms||r.ack_offset_ms||0));let svg='<svg width="1100" height="'+(60+rr.length*32)+'" viewBox="0 0 1100 '+(60+rr.length*32)+'"><text x="290" y="20">Time from batch start (ms); separate batches have independent origins</text>';const x=t=>290+Math.max(0,t)/max*780;for(let i=0;i<rr.length;i++){const r=rr[i],y=46+i*32;svg+='<text x="5" y="'+y+'" font-size="11">'+esc(r.case_id)+'</text>';const spans=[[r.arrival_offset_ms,r.submit_offset_ms,'#8896a6','Upload'],[r.submit_offset_ms,r.ack_offset_ms,'#356c99','Submit acknowledgment'],[r.queue_start_offset_ms,r.inference_start_offset_ms,'#80621e','VLM queue'],[r.inference_start_offset_ms,r.inference_end_offset_ms,'#1a6655','VLM job service']];for(const [a,b,c,label] of spans){if(a!=null&&b!=null&&b>=0)svg+='<rect x="'+x(a)+'" y="'+(y-11)+'" width="'+Math.max(2,x(b)-x(a))+'" height="12" fill="'+c+'"><title>'+label+' '+(b-a).toFixed(2)+' ms</title></rect>'}if(r.final_offset_ms!=null)svg+='<circle cx="'+x(r.final_offset_ms)+'" cy="'+(y-5)+'" r="4" fill="#17202a"><title>Observed '+(r.outcome_reached?'outcome: ':'deadline; unfinished: ')+esc(r.final_state)+'</title></circle>';}svg+='<text x="290" y="'+(55+rr.length*32)+'">0 ms</text><text x="980" y="'+(55+rr.length*32)+'">'+max.toFixed(1)+' ms</text></svg><p>Gray: upload · Blue: submit · Ochre: queue · Green: VLM job · Dot: observed automatic outcome or unfinished deadline (hover for status)</p>';document.getElementById('timeline').innerHTML=rr.length?svg:'N/A';}
selector.onchange=timeline;document.getElementById('filter').oninput=timeline;timeline();
section('vlm',S.vlm);section('llm',S.llm||S.language_default);section('policy',S.policy);section('escalation',S.escalation);section('reliability',S.reliability?{...S.reliability,load_observations:S.load_summary??null}:S.load_summary);section('security',S.security);
document.getElementById('failures').innerHTML=table(['Case','Suite','Status','Expected','Observed','Reason / policy'],D.correctness.filter(r=>r.status!=='passed').concat(D.requests.filter(r=>r.error).map(r=>({case_id:r.case_id,suite:'load',status:'unfinished',expected:'valid automatic outcome',actual:r.final_state,reason:r.error}))).map(r=>[r.case_id,r.suite,r.status,JSON.stringify(r.expected??null),JSON.stringify(r.actual??null),r.reason||r.policy_reference]));
document.getElementById('provenance').textContent=JSON.stringify(D.metadata,null,2);
</script></html>'''
    (Path(directory)/'report.html').write_text(template.replace('__DATA__',payload),encoding='utf-8')
    tests=summary['tests'];perf=summary.get('performance',[])
    lines=['# Evaluation — measured results',f"Run `{metadata['run_id']}`; timestamp {metadata['timestamp']}.",
        f"Source commit `{metadata['git_commit']}`; working tree dirty: {metadata['working_tree_dirty']}; source digest `{metadata['source_sha256']}`.",
        f"Timing scope: {metadata['timing_kind']}.",
        f"Checks: {tests['passed']} passed, {tests['failed']} failed, {tests['skipped']} skipped.",
        'Automatic outcome includes human-review/correction/handover waiting states; these are not final human resolutions.',
        'Bootstrap intervals are request-level and limited by within-batch correlation. p99 with small samples is unstable.']
    for p in perf:lines.append(f"- {p['scenario']}, {p['concurrency']} concurrent, {p['category']}, {p['arrival']}: n={p['n']}, acknowledgment mean {p['ack']['mean_ms']} ms, p95 {p['ack']['p95_ms']} ms, p99 {p['ack']['p99_ms']} ms; unfinished {p['unfinished']}.")
    if summary.get('policy'):lines.append(f"Policy labeled-case accuracy: {summary['policy']['accuracy']}; conflict labels excluded. Branch coverage: {summary['policy']['branch_coverage']}.")
    lines+=['Real VLM/LLM quality: see measured=true sections; unrun suites are N/A.',
        'Before/after improvement: N/A until two equivalent runs from the intended builds are supplied.',
        'Dataset: synthetic printed evidence and authored templates; results do not establish production accuracy or safety.',
        'Failure details and skipped explanations: failures.json and correctness.csv.']
    (Path(directory)/'evaluation.md').write_text('\n\n'.join(lines),encoding='utf-8')
